<script setup lang="ts">
import type { PackageFilters, PublisherSummary } from '~/types/api'
const props = defineProps<{ modelValue: PackageFilters; publishers: PublisherSummary[] }>()
const emit = defineEmits<{ 'update:modelValue': [value: PackageFilters] }>()
function update(key: keyof PackageFilters, value: string) { emit('update:modelValue', { ...props.modelValue, [key]: value, offset: 0 }) }
</script>
<template><aside class="surface-card p-5"><div class="flex items-center justify-between"><h2 class="font-bold">Filters</h2><button class="text-sm font-semibold text-link-700" type="button" @click="emit('update:modelValue', { q: modelValue.q, limit: modelValue.limit, offset: 0, sort: 'relevance' })">Clear all</button></div><div class="mt-5 grid gap-4"><label class="grid gap-1 text-sm font-semibold">Publisher<select class="rounded-lg border border-slate-300 bg-white p-2.5" :value="modelValue.publisher || ''" @change="update('publisher', ($event.target as HTMLSelectElement).value)"><option value="">Any publisher</option><option v-for="publisher in publishers" :key="publisher.id" :value="publisher.id">{{ publisher.name }}</option></select></label><label class="grid gap-1 text-sm font-semibold">Classification<select class="rounded-lg border border-slate-300 bg-white p-2.5" :value="modelValue.classification || ''" @change="update('classification', ($event.target as HTMLSelectElement).value)"><option value="">Any classification</option><option value="first-party">First Party</option><option value="reviewed-community">Reviewed Community</option></select></label><label class="grid gap-1 text-sm font-semibold">Channel<select class="rounded-lg border border-slate-300 bg-white p-2.5" :value="modelValue.channel || ''" @change="update('channel', ($event.target as HTMLSelectElement).value)"><option value="">Any channel</option><option value="stable">Stable</option><option value="beta">Beta</option><option value="nightly">Nightly</option></select></label><label class="grid gap-1 text-sm font-semibold">Host version<input class="rounded-lg border border-slate-300 p-2.5" :value="modelValue.host || ''" placeholder="e.g. 0.2.0" @input="update('host', ($event.target as HTMLInputElement).value)"></label><label class="grid gap-1 text-sm font-semibold">SDK version<input class="rounded-lg border border-slate-300 p-2.5" :value="modelValue.sdk || ''" placeholder="e.g. 1.9.0" @input="update('sdk', ($event.target as HTMLInputElement).value)"></label></div></aside></template>
